CH=[(0,1,2),(3,4)]
def discs(pos):
    out=[]
    for ch in CH:
        n=len(ch); sr=sum(pos[i][0] for i in ch); sc=sum(pos[i][1] for i in ch)
        out.append((sr//n, sc//n))
