    for i in range(5):
        if i!=pl: res.append(((tuple(pos[:i]+(pos[i],)+pos[i+1:]) if False else pos, i)))
    # disc moves
    for j,ch in enumerate(CH):
        if pl not in ch: continue
        x=xd[j]
        if covered(pos,xd,x): continue
        np_=list(pos); np_[pl]=x
        nxd=discs(np_)
        if ok(np_,nxd): res.append((tuple(np_),pl))
    # teleports
    for k,rc in RING.items():
