import collections
ODASH=((48,39),(48,41),(49,38),(49,42),(50,37),(50,43),(52,37),(52,43),(53,38),(53,42),(54,39),(54,41))
PDASH=((15,56),(15,58),(16,55),(16,59),(17,54),(17,60),(19,54),(19,60),(20,55),(20,59),(21,56),(21,58))
def env(f):
    a=f.ascii.split('\n')
    S=frozenset((r,c) for r in range(64) for c in range(64) if a[r][c]=='S')
    return S
def dc(c):
    r,c0=c; return frozenset((r+dr,c0+dk) for dr in range(-2,3) for dk in range(-2,3) if abs(dr)+abs(dk)<=2)
def xc(c):
    r,c0=c; return frozenset((r+dr,c0+dk) for dr in range(-2,3) for dk in range(-2,3) if not(abs(dr)==2 and abs(dk)==2))
CH=((0,1,2),(3,4)); RINGS=((51,40),(18,57)); OD=frozenset(ODASH); PD=frozenset(PDASH)
def dsc(pos):
    return tuple((sum(pos[i][0] for i in ch)//len(ch), sum(pos[i][1] for i in ch)//len(ch)) for ch in CH)
def valid(pos,S):
    for p in pos:
        if dc(p)&S: return False
    for x in dsc(pos):
        if xc(x)&S: return False
    return True
def iswin(pos):
    x=dsc(pos); return bool(xc(x[0])&OD) and bool(xc(x[1])&PD)
def nbrs(st,S):
    pos,pl=st; x=dsc(pos); out=[]
    for i in range(5):
        if i!=pl: out.append((pos,i))
    for j,ch in enumerate(CH):
        if pl in ch and not any(x in dc(p) for p in pos):
            np_=list(pos); np_[pl]=x; np_=tuple(np_)
            if valid(np_,S): out.append((np_,pl))
    for rc in RINGS:
        if not any(rc in dc(p) for p in pos):
            np_=list(pos); np_[pl]=rc; np_=tuple(np_)
            if valid(np_,S): out.append((np_,pl))
    return out
def solve(f, start, p0, maxd=14, cap=500000):
    S=env(f)
    st=(start,p0); q=collections.deque([(st,[])]); seen={st}; exp=0
    while q:
        s,path=q.popleft()
        if len(path)>=maxd: continue
        for ns in nbrs(s,S):
            if ns in seen: continue
            seen.add(ns); exp+=1
            p2=path+[ns]
            if iswin(ns[0]): return p2, len(seen)
            q.append((ns,p2))
            if exp>cap: return None,len(seen)
    return None,len(seen)
