def astarO(f, start, p0, cap=250000, maxd=20):
    import heapq
    S=env(f)
    OD=frozenset([(48,39),(48,41),(49,38),(49,42),(50,37),(50,43),(52,37),(52,43),(53,38),(53,42),(54,39),(54,41)])
    RINGS=((51,40),(18,57))
    PFIX=((35,45),(48,54))
    def disc(pos): return (sum(p[0] for p in pos)//3, sum(p[1] for p in pos)//3)
    def bbox(c): return (c[0]-2,c[0]+2,c[1]-2,c[1]+2)
    def inbb(cell,c):
        r0,r1,c0,c1=bbox(c); return r0<=cell[0]<=r1 and c0<=cell[1]<=c1
    def valid(pos,x):
        for p in pos:
            if dc2(p)&S: return False
        return not (xc2(x)&S)
    def nbrs(st):
        pos,pl=st; x=disc(pos); out=[]
        for i in range(3):
            if i!=pl: out.append((pos,i))
        allb=list(pos)+list(PFIX)
        for dr in range(-2,3):
            for dk in range(-2,3):
                cell=(x[0]+dr,x[1]+dk)
                if any(inbb(cell,c) for c in allb): continue
                np_=list(pos); np_[pl]=cell; np_=tuple(np_)
                nx=disc(np_)
                if valid(np_,nx): out.append((np_,pl))
        for rc in RINGS:
            if any(inbb(rc,c) for c in allb): continue
            np_=list(pos); np_[pl]=rc; np_=tuple(np_)
            if valid(np_,disc(np_)): out.append((np_,pl))
        return out
    def h(st):
        x=disc(st[0]); return max(abs(x[0]-51),abs(x[1]-40))
    st=(start,p0)
    if xc2(disc(start))&OD: return []
    pq=[(h(st),0,st,None)]; best={st}; par={}
    exp=0
    while pq:
        _,g,s,_=heapq.heappop(pq)
        exp+=1
        if exp>cap: return None
        for ns in nbrs(s):
            if ns in best and best[ns]<=g+1: continue
            best[ns]=g+1; par[ns]=(s,g+1)
            if xc2(disc(ns[0]))&OD:
                path=[]; cur=ns
                while cur in par:
                    path.append(cur); cur=par[cur][0]
                return path
            heapq.heappush(pq,(g+1+h(ns),g+1,ns,None))
    return None
