    def dsc(pos): return (sum(p[0] for p in pos)//n, sum(p[1] for p in pos)//n)
    def inbb(cell,c): return abs(cell[0]-c[0])<=2 and abs(cell[1]-c[1])<=2
    def okall(pos,x): return all(p in FI for p in pos) and (x in FD)
    def nbrs(st):
        pos,pl=st; x=dsc(pos); out=[]
        for i in range(n):
            if i!=pl: out.append(((pos,i),('des',i)))
        obs=list(pos)+list(fixed)
        for dr in range(-2,3):
            for dk in range(-2,3):
                cell=(x[0]+dr,x[1]+dk)
                if any(inbb(cell,c) for c in obs): continue
                if cell not in FI: continue
                np_=list(pos); np_[pl]=cell; np_=tuple(np_)
                nx=dsc(np_)
                if nx in FD: out.append(((np_,pl),('cell',cell)))
        for rc in rings:
            if any(inbb(rc,c) for c in obs): continue
            if rc not in FI: continue
            np_=list(pos); np_[pl]=rc; np_=tuple(np_)
            if dsc(np_) in FD: out.append(((np_,pl),('ring',rc)))
        return out
    st=(start,p0)
    cur={st:[]}
    seen={st}
    for it in range(depth):
        nxt={}
        for s,path in cur.items():
            for ns,a in nbrs(s):
                if ns in seen: continue
                seen.add(ns)
                p2=path+[a]
                if xc2(dsc(ns[0]))&set(dash): return p2,'FOUND'
                key=ns
