def beam_to(start,p0,fixed,goalc,rings,allowed,depth=10,beam=400,costcap=16):
    import heapq
    CELLS=[(dr,dc) for dr in range(-2,3) for dc in range(-2,3)]
    n=len(start)
    def dcen(pos): return (sum(p[0] for p in pos)//n,sum(p[1] for p in pos)//n)
    def inb(a,c): return abs(a[0]-c[0])<=2 and abs(a[1]-c[1])<=2
    def h(pos):
        c=dcen(pos)
        if c in goalc: return 0
        return min(max(abs(c[0]-g[0]),abs(c[1]-g[1])) for g in goalc)
    def macros(st):
        pos,pl=st; x=dcen(pos); out=[]; obs=list(pos)+list(fixed)
        for i in range(n):
            cost=1 if i==pl else 2
            for dr,dk in CELLS:
                cell=(x[0]+dr,x[1]+dk)
                if any(inb(cell,c) for c in obs): continue
                np_=list(pos); np_[i]=cell; np_=tuple(np_)
                if allowed(dcen(np_)): out.append(((np_,i),cost,('mov',i,cell)))
            for rc in rings:
                if any(inb(rc,c) for c in obs): continue
                np_=list(pos); np_[i]=rc; np_=tuple(np_)
                if allowed(dcen(np_)): out.append(((np_,i),cost,('ring',i,rc)))
        return out
    st=(tuple(start),p0)
    if dcen(start) in goalc: return [],0
    cur={st:(0,[])}
    for d in range(depth):
        nxt={}
        for s,(g,path) in cur.items():
            for ns,c,a in macros(s):
                g2=g+c
                if g2>costcap: continue
                if dcen(ns[0]) in goalc: return path+[a],g2
                if g2<nxt.get(ns,(999,))[0]: nxt[ns]=(g2,path+[a])
        if not nxt: return None,'dead'
        items=sorted(nxt.items(),key=lambda kv: kv[1][0]+3.0*h(kv[0][0]))[:beam]
        cur=dict(items)
    return None,'depth'
